var CONTINUT_PROBABILITATE={};
CONTINUT_PROBABILITATE["teorema-lui-bayes"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Probabilitatea evenimentului A știind că B s-a produs, exprimată prin probabilitățile inițiale și probabilitatea lui B sub A.</div>",formula_display:"P(A|B) = P(B|A) · P(A) / P(B)",diagrama:"<svg viewBox=\"0 0 320 180\" xmlns=\"http://www.w3.org/2000/svg\" width=\"320\"><circle cx=\"125\" cy=\"95\" r=\"62\" fill=\"rgba(176,96,0,0.15)\" stroke=\"#b06000\" stroke-width=\"2\"/><circle cx=\"195\" cy=\"95\" r=\"62\" fill=\"rgba(200,146,42,0.25)\" stroke=\"#c8922a\" stroke-width=\"2\"/><text x=\"85\" y=\"55\" font-size=\"16\" fill=\"#b06000\" font-weight=\"600\">A</text><text x=\"235\" y=\"55\" font-size=\"16\" fill=\"#a87418\" font-weight=\"600\">B</text><text x=\"160\" y=\"99\" font-size=\"11\" text-anchor=\"middle\" fill=\"#1a1510\">A∩B</text><text x=\"160\" y=\"155\" text-anchor=\"middle\" font-size=\"12\" fill=\"#555\" font-style=\"italic\">P(A|B) = ce parte din B se suprapune cu A</text></svg>",intuitiv_text:"<span class=\"hl\">Teorema lui Bayes te ajută să-ți schimbi părerea când afli ceva nou</span>. Nu știi dacă afară plouă, dar crezi că e puțin probabil. Apoi vezi pe cineva intrând cu umbrela udă leoarcă. Acum crezi mult mai tare că plouă. Bayes este rețeta exactă prin care „bănuiala de dinainte” devine „bănuiala de după indiciu”.",intuitiv_nota:"Thomas Bayes a formulat ideea în 1763, iar astăzi ea stă la baza statisticii bayesiene, folosită în filtrele anti-spam, în diagnosticul medical și în navigația autonomă.",exercitii:[{"q":"Se știe P(A)=0.3, P(B|A)=0.8 și P(B)=0.4. Calculează P(A|B) folosind formula lui Bayes.","pasi":["Formula spune P(A|B) = P(B|A) · P(A) / P(B).","Înlocuim valorile cunoscute: P(A|B) = 0.8 × 0.3 / 0.4.","Calculăm pas cu pas: 0.8 × 0.3 = 0.24, apoi 0.24 / 0.4 = 0.6."],"r":"✓ P(A|B) = <strong>0.6</strong>"},{"q":"Se știe P(A|B)=0.7, P(B)=0.4 și P(A)=0.5. Găsește probabilitatea inversă P(B|A).","pasi":["P(A|B)·P(B) și P(B|A)·P(A) sunt amândouă egale cu P(A∩B), deci P(B|A) = P(A|B) × P(B) / P(A).","Înlocuim: P(B|A) = 0.7 × 0.4 / 0.5.","Calculăm: 0.7 × 0.4 = 0.28, apoi 0.28 / 0.5 = 0.56."],"r":"✓ P(B|A) = <strong>0.56</strong>"},{"q":"P(A)=0.5, iar dovada B este la fel de probabilă indiferent dacă A se întâmplă sau nu: P(B|A)=P(B|Ā)=0.5. Calculează P(A|B).","pasi":["Aflăm întâi P(B) = P(B|A)P(A) + P(B|Ā)P(Ā) = 0.5×0.5 + 0.5×0.5 = 0.5.","Aplicăm Bayes: P(A|B) = 0.5×0.5/0.5 = 0.5.","Observăm că P(A|B) = P(A): dovada B nu a schimbat cu nimic bănuiala inițială."],"r":"✓ P(A|B) = <strong>0.5</strong>, la fel ca P(A) - B este o dovadă neinformativă"},{"q":"Adevărat sau fals: probabilitatea posterioară P(A|B) este întotdeauna mai mare decât probabilitatea inițială P(A)?","pasi":["Fals. La exercițiul anterior am văzut un caz în care P(A|B)=P(A), deci dovada nu schimbă nimic.","Dacă dovada B apare mai des când A NU se întâmplă, P(A|B) poate fi chiar mai mică decât P(A).","Direcția și mărimea actualizării depind complet de cât de „specifică” este dovada pentru A."],"r":"✓ <strong>Fals</strong> - posteriorul poate fi mai mare, egal sau mai mic decât priorul"},{"q":"Un test medical detectează o boală rară: P(boală)=0.001 (1 din 1000 persoane). Testul e pozitiv la 99% dintre bolnavi, dar dă și 1% fals-pozitive la persoanele sănătoase. Dacă cineva testat iese pozitiv, ce șansă are să fie cu adevărat bolnav?","pasi":["Calculăm întâi probabilitatea totală de rezultat pozitiv: P(+) = 0.99×0.001 + 0.01×0.999 = 0.00099 + 0.00999 = 0.0109.","Aplicăm Bayes: P(boală|+) = P(+|boală)×P(boală) / P(+) = 0.00099 / 0.0109 ≈ 0.0908.","Deși testul pare foarte precis, boala e atât de rară încât majoritatea rezultatelor pozitive vin de la oameni sănătoși testați greșit."],"r":"✓ ≈<strong>9.1%</strong> - acesta este „paradoxul bazei rare”, un rezultat corect dar contraintuitiv"}]};
CONTINUT_PROBABILITATE["teorema-centrala-limita"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Dacă X₁,X₂,... v.a. iid cu E[X]=μ și Var(X)=σ²&lt;∞, suma standardizată converge în distribuție la N(0,1).</div>",formula_display:"√n(X̄-μ)/σ →^d N(0,1)",diagrama:"<svg viewBox=\"0 0 320 180\" xmlns=\"http://www.w3.org/2000/svg\" width=\"320\"><text x=\"48\" y=\"15\" text-anchor=\"middle\" font-size=\"11\" fill=\"#555\" font-style=\"italic\">distribuție oarecare</text><rect x=\"15\" y=\"110\" width=\"16\" height=\"40\" fill=\"#b06000\"/><rect x=\"35\" y=\"80\" width=\"16\" height=\"70\" fill=\"#b06000\"/><rect x=\"55\" y=\"120\" width=\"16\" height=\"30\" fill=\"#b06000\"/><rect x=\"75\" y=\"95\" width=\"16\" height=\"55\" fill=\"#b06000\"/><line x1=\"10\" y1=\"150\" x2=\"95\" y2=\"150\" stroke=\"#1a1510\" stroke-width=\"1.5\"/><text x=\"122\" y=\"118\" text-anchor=\"middle\" font-size=\"12\" fill=\"#1a1510\">n → ∞</text><line x1=\"100\" y1=\"128\" x2=\"143\" y2=\"128\" stroke=\"#1a1510\" stroke-width=\"1.5\"/><line x1=\"135\" y1=\"122\" x2=\"143\" y2=\"128\" stroke=\"#1a1510\" stroke-width=\"1.5\"/><line x1=\"135\" y1=\"134\" x2=\"143\" y2=\"128\" stroke=\"#1a1510\" stroke-width=\"1.5\"/><text x=\"228\" y=\"15\" text-anchor=\"middle\" font-size=\"11\" fill=\"#555\" font-style=\"italic\">sumă standardizată</text><line x1=\"145\" y1=\"150\" x2=\"310\" y2=\"150\" stroke=\"#1a1510\" stroke-width=\"1.5\"/><path d=\"M150,150 C175,150 190,42 227,40 C264,42 280,150 305,150\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"2.5\"/></svg>",intuitiv_text:"Aruncă un zar de puține ori și adună numerele - suma pare neregulată, aleatoare. Dar dacă repeți asta de foarte multe ori și notezi de fiecare dată suma, toate acele sume, puse cap la cap, desenează aceeași formă de clopot - indiferent cum arată zarul, chiar și unul ciudat, cu fețe inegale. <span class=\"hl\">Oricâte lucruri mici și independente aduni, rezultatul final seamănă aproape mereu cu un clopot</span>, chiar dacă nicio bucățică din el nu are formă de clopot.",intuitiv_nota:"De Moivre a schițat ideea încă din 1733, iar Laplace și apoi Lyapunov (1901) au dus-o mai departe și au rafinat-o. E considerat cel mai important rezultat din teoria probabilităților și stă la baza statisticii inferențiale.",exercitii:[{"q":"La un test, notele au media μ=50 și deviația standard σ=10. Pentru un eșantion de n=50 elevi, calculează probabilitatea ca media notelor eșantionului să depășească 52.","pasi":["Conform TCL, media eșantionului X̄ₙ este aproximativ normală cu deviația standard σ/√n = 10/√50 ≈ 1.414.","Standardizăm: Z = (52-50)/1.414 ≈ 1.414.","Din tabelul normal, P(Z&gt;1.414) ≈ 1 - 0.9214 = 0.0786."],"r":"✓ ≈<strong>7.9%</strong>"},{"q":"Aruncăm o monedă corectă de n ori și urmărim proporția de capete. Câte aruncări sunt necesare ca deviația standard a acestei proporții să scadă sub 0.01?","pasi":["Deviația standard a proporției este σ = √(p(1-p)/n) = √(0.25/n).","Punem condiția √(0.25/n) &lt; 0.01, adică 0.25/n &lt; 0.0001.","Rezolvăm: n &gt; 0.25/0.0001 = 2500, deci sunt necesare cel puțin 2501 aruncări."],"r":"✓ n ≥ <strong>2501</strong> aruncări"},{"q":"Dacă variabilele X_i sunt deja normal distribuite (nu doar aproximativ), ce se întâmplă cu media eșantionului X̄ₙ, chiar și pentru n=1?","pasi":["TCL e un rezultat de aproximare pentru n mare, dar dacă distribuția inițială e deja normală, suma (și media) rămân exact normale pentru orice n, chiar n=1.","Acesta e cazul-limită „perfect”: nu mai e nevoie de n mare, aproximarea devine egalitate exactă."],"r":"✓ X̄ₙ este <strong>exact normală pentru orice n</strong>, nu doar aproximativ"},{"q":"Adevărat sau fals: teorema centrală limită garantează că datele individuale X_i devin normal distribuite atunci când n este mare.","pasi":["Fals - aceasta e o confuzie foarte des întâlnită.","TCL vorbește despre distribuția mediei (sau sumei) eșantionului, X̄ₙ, nu despre fiecare observație individuală X_i.","Datele individuale își păstrează distribuția lor originală (uniformă, exponențială etc.) oricât de mare ar fi n."],"r":"✓ <strong>Fals</strong> - TCL se referă la media eșantionului, nu la datele individuale"},{"q":"Aruncăm o monedă corectă de 1000 de ori. Folosind TCL, aproximează probabilitatea de a obține mai mult de 530 capete.","pasi":["Numărul de capete X e suma a 1000 aruncări Bernoulli(0.5): μ=np=500, σ=√(np(1-p))=√250≈15.81.","Standardizăm: Z=(530-500)/15.81≈1.9.","Din tabelul normal: P(Z&gt;1.9)≈1-0.9713=0.0287."],"r":"✓ ≈<strong>2.9%</strong>"}]};
CONTINUT_PROBABILITATE["legea-numerelor-mari"]={definitie:"<div class=\"def-box\"><strong>Enunț (forma slabă):</strong> Media aritmetică X̄ₙ a n observații iid converge în probabilitate la media teoretică μ.</div>",formula_display:"X̄ₙ →^P μ (pentru orice ε&gt;0: P(|X̄ₙ-μ|&gt;ε)→0)",diagrama:"<svg viewBox=\"0 0 320 180\" xmlns=\"http://www.w3.org/2000/svg\" width=\"320\"><line x1=\"30\" y1=\"20\" x2=\"30\" y2=\"150\" stroke=\"#1a1510\" stroke-width=\"1.5\"/><line x1=\"30\" y1=\"150\" x2=\"300\" y2=\"150\" stroke=\"#1a1510\" stroke-width=\"1.5\"/><line x1=\"30\" y1=\"60\" x2=\"300\" y2=\"60\" stroke=\"#c8922a\" stroke-width=\"1.5\" stroke-dasharray=\"4,4\"/><text x=\"305\" y=\"64\" font-size=\"12\" fill=\"#a87418\">p</text><path d=\"M35,100 L50,35 L65,115 L80,45 L95,95 L115,55 L140,80 L170,50 L200,68 L230,58 L260,63 L290,60\" fill=\"none\" stroke=\"#b06000\" stroke-width=\"2\"/><text x=\"165\" y=\"168\" text-anchor=\"middle\" font-size=\"11\" fill=\"#555\" font-style=\"italic\">număr de încercări (n)</text><text x=\"14\" y=\"90\" font-size=\"11\" fill=\"#555\" font-style=\"italic\" transform=\"rotate(-90 14 90)\">frecvență</text></svg>",intuitiv_text:"Arunci o monedă de multe ori și numeri de câte ori a picat cap. La început procentul sare mult, în sus și în jos - poate fi chiar 100% după o singură aruncare norocoasă. Dar cu cât arunci mai mult, cu atât acest procent se apropie tot mai mult de jumătate. <span class=\"hl\">Cu cât repeți un joc de mai multe ori, cu atât media rezultatelor se apropie de valoarea „adevărată”</span>, cea pe care ai obține-o dacă ai putea juca la nesfârșit.",intuitiv_nota:"Jacob Bernoulli a demonstrat prima formă în 1713, iar Borel a adăugat, în 1909, forma tare - convergența aproape sigură. Împreună formează baza empirică a statisticii.",exercitii:[{"q":"Un zar corect este aruncat de foarte multe ori. La ce valoare converge media aritmetică a rezultatelor obținute?","pasi":["Media teoretică a unui zar este μ = (1+2+3+4+5+6)/6 = 21/6.","Calculăm: 21/6 = 3.5.","Legea numerelor mari spune că media observată se apropie de această valoare când n crește."],"r":"✓ Media converge la <strong>3.5</strong>"},{"q":"Un jucător aruncă o monedă necunoscută de 10000 ori și observă 6200 capete, adică o frecvență de 0.62. Ce concluzie sugerează legea numerelor mari despre p, probabilitatea reală de a obține cap?","pasi":["Pentru n mare, legea numerelor mari spune că frecvența relativă observată e foarte aproape de probabilitatea reală p.","Aici n=10000 e suficient de mare încât abaterea de la p să fie foarte improbabilă dacă moneda ar fi corectă (p=0.5).","Concluzia rezonabilă e că p ≈ 0.62, adică moneda e probabil trucată, nu corectă."],"r":"✓ p ≈ <strong>0.62</strong> - moneda pare trucată"},{"q":"Pentru n=1 (o singură aruncare a monedei), ce spune legea numerelor mari despre frecvența relativă obținută?","pasi":["Legea numerelor mari e un rezultat despre limită, valabil doar când n crește spre infinit.","Pentru n=1 frecvența relativă e fie 0, fie 1 - complet diferită de p=0.5, iar legea nu se aplică deloc.","Abia pe măsură ce n crește, frecvența începe să se apropie de p."],"r":"✓ La n=1 <strong>legea nu spune nimic</strong> - convergența apare doar pentru n mare"},{"q":"Adevărat sau fals: legea numerelor mari garantează că, după multe aruncări, numărul de capete și numărul de cozi devin aproape egale.","pasi":["Fals - aceasta e o confuzie foarte răspândită, numită uneori „legea mediilor” sau greșeala jucătorului.","Legea numerelor mari se referă la frecvența relativă (proporția), nu la diferența absolută dintre numărul de capete și cozi.","De fapt, diferența absolută dintre numărul de capete și cozi tinde să crească pe măsură ce n crește, chiar dacă raportul lor se apropie de 1."],"r":"✓ <strong>Fals</strong> - doar proporția converge, nu diferența absolută"},{"q":"O fabrică testează 5000 de becuri și găsește 47 defecte. Folosind legea numerelor mari, estimează procentul de becuri defecte din toată producția.","pasi":["Frecvența relativă observată e 47/5000 = 0.0094, adică 0.94%.","Eșantionul de 5000 e suficient de mare încât, prin legea numerelor mari, frecvența relativă să fie o estimare de încredere a probabilității reale de defect.","Estimăm deci că aproximativ 0.94% din toată producția e defectă."],"r":"✓ Estimare: <strong>≈0.94%</strong> becuri defecte"}]};
CONTINUT_PROBABILITATE["inegalitatea-lui-chebyshev"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Pentru orice v.a. X cu medie μ și varianță σ² finită, probabilitatea că X deviază de la medie cu mai mult de kσ este ≤1/k².</div>",formula_display:"P(|X-μ| ≥ kσ) ≤ 1/k²",diagrama:"<svg viewBox=\"0 0 320 180\" xmlns=\"http://www.w3.org/2000/svg\" width=\"320\"><line x1=\"30\" y1=\"150\" x2=\"300\" y2=\"150\" stroke=\"#1a1510\" stroke-width=\"1.5\"/><path d=\"M35,148 C55,148 50,70 90,55 C130,42 150,115 175,95 C205,72 215,140 250,146 C270,149 285,150 295,150\" fill=\"rgba(176,96,0,0.12)\" stroke=\"#b06000\" stroke-width=\"2\"/><line x1=\"95\" y1=\"28\" x2=\"95\" y2=\"150\" stroke=\"#c8922a\" stroke-width=\"1.5\" stroke-dasharray=\"4,4\"/><line x1=\"230\" y1=\"28\" x2=\"230\" y2=\"150\" stroke=\"#c8922a\" stroke-width=\"1.5\" stroke-dasharray=\"4,4\"/><text x=\"95\" y=\"20\" text-anchor=\"middle\" font-size=\"11\" fill=\"#a87418\">μ-kσ</text><text x=\"230\" y=\"20\" text-anchor=\"middle\" font-size=\"11\" fill=\"#a87418\">μ+kσ</text><text x=\"162\" y=\"168\" text-anchor=\"middle\" font-size=\"12\" fill=\"#555\" font-style=\"italic\">P(în afara benzii) ≤ 1/k² - pentru orice formă</text></svg>",intuitiv_text:"Într-o clasă, majoritatea copiilor au înălțimi apropiate de medie, dar câțiva sunt mult mai înalți sau mai scunzi. <span class=\"hl\">Inegalitatea lui Cebîșev garantează că, oricât de ciudat ar arăta „amestecul” de înălțimi, nu prea mulți copii pot fi foarte departe de medie</span>. Dacă te uiți la o bandă de 2 pași de medie în fiecare parte, cel mult un sfert dintre copii pot fi în afara ei - garantat, indiferent cum arată distribuția înălțimilor.",intuitiv_nota:"Pafnuty Cebîșev a publicat-o în 1867. E mai slabă decât regula 68-95-99.7 a normalei, dar are un avantaj mare - funcționează pentru orice distribuție.",exercitii:[{"q":"Pentru o variabilă aleatoare X cu medie μ și deviație standard σ (distribuție necunoscută), calculează un majorant pentru P(|X-μ|≥2σ).","pasi":["Aplicăm direct inegalitatea lui Cebîșev cu k=2: P(|X-μ|≥kσ) ≤ 1/k².","Înlocuim: 1/2² = 1/4.","Deci probabilitatea ca X să se abată cu cel puțin 2 deviații standard de la medie e cel mult 1/4."],"r":"✓ ≤<strong>25%</strong>"},{"q":"Ce valoare a lui k garantează P(|X-μ|≥kσ)≤0.01, oricare ar fi distribuția lui X?","pasi":["Pornim de la 1/k² ≤ 0.01.","Inversăm: k² ≥ 1/0.01 = 100.","Extragem radical: k ≥ 10."],"r":"✓ k ≥ <strong>10</strong>"},{"q":"Ce spune inegalitatea lui Cebîșev pentru k=1, adică pentru P(|X-μ|≥σ)?","pasi":["Cu k=1: 1/k² = 1/1² = 1.","Inegalitatea devine P(|X-μ|≥σ) ≤ 1, ceea ce e adevărat pentru orice probabilitate, oricum ar arăta distribuția.","Pentru k=1 inegalitatea nu spune nimic folositor - devine informativă abia pentru k&gt;1."],"r":"✓ Pentru k=1 inegalitatea e <strong>banală</strong> (P≤1, oricum adevărat)"},{"q":"Adevărat sau fals: inegalitatea lui Cebîșev oferă întotdeauna cea mai bună (cea mai strânsă) estimare posibilă a probabilității cozii, pentru orice distribuție.","pasi":["Fals. Cebîșev e un majorant universal, valabil pentru orice distribuție, dar tocmai de aceea e adesea foarte „larg”.","De exemplu, pentru distribuția normală, la 2σ, Cebîșev garantează doar P≤25%, dar valoarea reală e mult mai mică, ≈4.55%.","Cu cât știm mai multe despre forma distribuției, cu atât putem obține estimări mai precise decât Cebîșev."],"r":"✓ <strong>Fals</strong> - Cebîșev e universal, dar de obicei mult mai slab decât valoarea exactă"},{"q":"Timpul mediu de livrare al unei companii e μ=30 minute, cu deviație standard σ=5 minute (forma distribuției nu e cunoscută). Estimează, cu Cebîșev, un majorant pentru probabilitatea ca o livrare să se abată cu cel puțin 20 minute de la medie.","pasi":["Abaterea de 20 minute corespunde la k=20/σ=20/5=4 deviații standard.","Aplicăm Cebîșev: P(|X-μ|≥4σ) ≤ 1/4².","Calculăm: 1/16 = 0.0625."],"r":"✓ ≤<strong>6.25%</strong>"}]};
CONTINUT_PROBABILITATE["distributia-normala"]={definitie:"<div class=\"def-box\"><strong>Definiție:</strong> Distribuția normală (Gaussiană) N(μ,σ²) cu media μ și deviația standard σ, cu densitate de formă bell-curve.</div>",formula_display:"f(x) = (1/σ√2π)·exp(-(x-μ)²/(2σ²))",diagrama:"<svg viewBox=\"0 0 320 180\" xmlns=\"http://www.w3.org/2000/svg\" width=\"320\"><rect x=\"130\" y=\"20\" width=\"70\" height=\"130\" fill=\"rgba(200,146,42,0.28)\"/><line x1=\"30\" y1=\"150\" x2=\"300\" y2=\"150\" stroke=\"#1a1510\" stroke-width=\"1.5\"/><path d=\"M35,150 C90,150 100,20 165,20 C230,20 240,150 295,150\" fill=\"none\" stroke=\"#b06000\" stroke-width=\"2.5\"/><line x1=\"165\" y1=\"18\" x2=\"165\" y2=\"150\" stroke=\"#7a4400\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/><text x=\"165\" y=\"14\" text-anchor=\"middle\" font-size=\"12\" fill=\"#7a4400\">μ</text><text x=\"130\" y=\"167\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">μ-σ</text><text x=\"200\" y=\"167\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">μ+σ</text><text x=\"165\" y=\"105\" text-anchor=\"middle\" font-size=\"12\" fill=\"#7a4400\" font-weight=\"600\">68%</text></svg>",intuitiv_text:"Dacă cântărești sute de mere culese dintr-un pom și notezi câte mere au fiecare greutate, obții un deal rotunjit: puține mere foarte mici, puține foarte mari și cele mai multe undeva la mijloc. <span class=\"hl\">Acest „deal” în formă de clopot este distribuția normală</span> și apare aproape peste tot: înălțimea copiilor, greutatea merelor, erorile unui cântar care nu e perfect exact.",intuitiv_nota:"Carl Friedrich Gauss (1809) a folosit-o pentru a descrie erorile de măsurare astronomice. Regula 68-95-99.7: 68% din observații sunt în ±σ, 95% în ±2σ, 99.7% în ±3σ.",exercitii:[{"q":"Notele la un test standardizat urmează X~N(100,225), adică μ=100 și σ²=225. Calculează P(X&gt;115).","pasi":["Aflăm σ=√225=15.","Standardizăm: Z=(115-100)/15=1.","Din tabelul normal: P(Z&gt;1)=1-0.8413=0.1587."],"r":"✓ ≈<strong>15.87%</strong>"},{"q":"X~N(50,16), adică μ=50 și σ=4. Găsește valoarea x pentru care P(X&lt;x)=0.9772.","pasi":["Căutăm în tabelul normal standard z astfel încât Φ(z)=0.9772: acesta e z=2.","Trecem la scara lui X: x=μ+zσ=50+2×4.","Calculăm: x=50+8=58."],"r":"✓ x=<strong>58</strong>"},{"q":"În ce caz particular variabila standardizată Z=(X-μ)/σ este identică cu X însuși?","pasi":["Standardizarea mută media la 0 și scalează deviația standard la 1.","Dacă X are deja μ=0 și σ=1, adică X~N(0,1), atunci Z=(X-0)/1=X.","Acesta e cazul „normal standard” - motivul pentru care tabelele de probabilitate se construiesc pentru N(0,1)."],"r":"✓ Cazul special: <strong>X~N(0,1)</strong>, distribuția normală standard"},{"q":"Adevărat sau fals: pentru distribuția normală, media, mediana și modul sunt întotdeauna egale.","pasi":["Adevărat.","Distribuția normală e perfect simetrică față de μ, deci jumătate din probabilitate e de fiecare parte - asta face din μ mediana.","Vârful clopotului, adică valoarea cea mai probabilă, e tot în μ, deci μ e și modul."],"r":"✓ <strong>Adevărat</strong> - media = mediana = modul = μ"},{"q":"Temperaturile de vară dintr-un oraș urmează N(28,4), adică μ=28°C și σ=2°C. Ce procent din zilele de vară au temperatura între 26°C și 30°C?","pasi":["Observăm că 26=μ-σ și 30=μ+σ, adică intervalul e exact banda de o deviație standard în jurul mediei.","Regula 68-95-99.7 spune că aproximativ 68% din valori cad în intervalul (μ-σ, μ+σ).","Deci aproximativ 68% din zilele de vară au temperatura în acest interval."],"r":"✓ ≈<strong>68%</strong> din zile"}]};
CONTINUT_PROBABILITATE["probabilitatea-conditionata"]={definitie:"<div class=\"def-box\"><strong>Definiție:</strong> Probabilitatea evenimentului A condiționat de apariția evenimentului B (P(B)&gt;0).</div>",formula_display:"P(A|B) = P(A∩B) / P(B)",diagrama:"<svg viewBox=\"0 0 320 180\" xmlns=\"http://www.w3.org/2000/svg\" width=\"320\"><rect x=\"10\" y=\"15\" width=\"300\" height=\"150\" fill=\"none\" stroke=\"#1a1510\" stroke-width=\"1.5\" rx=\"4\"/><text x=\"20\" y=\"30\" font-size=\"12\" fill=\"#555\" font-style=\"italic\">Ω</text><circle cx=\"130\" cy=\"95\" r=\"55\" fill=\"rgba(176,96,0,0.15)\" stroke=\"#b06000\" stroke-width=\"2\"/><circle cx=\"190\" cy=\"95\" r=\"55\" fill=\"rgba(200,146,42,0.3)\" stroke=\"#c8922a\" stroke-width=\"2\"/><text x=\"95\" y=\"60\" font-size=\"16\" fill=\"#b06000\" font-weight=\"600\">A</text><text x=\"225\" y=\"60\" font-size=\"16\" fill=\"#a87418\" font-weight=\"600\">B</text><text x=\"160\" y=\"99\" font-size=\"11\" text-anchor=\"middle\" fill=\"#1a1510\">A∩B</text><text x=\"160\" y=\"150\" text-anchor=\"middle\" font-size=\"12\" fill=\"#555\" font-style=\"italic\">P(A|B): noul univers devine B</text></svg>",intuitiv_text:"Ai un bol cu bile: unele roșii, altele albastre, unele mari, altele mici. Cineva îți spune „am scos o bilă mare”, fără să-ți zică culoarea. <span class=\"hl\">Acum, ca să afli probabilitatea ca bila să fie roșie, te uiți doar la bilele mari, nu la toate bilele din bol</span>. Ai „micșorat” bolul doar la bilele mari - asta e probabilitatea condiționată.",intuitiv_nota:"Ideea de condiționare stă la baza teoremei lui Bayes și a proceselor stocastice - e unul dintre conceptele fundamentale ale teoriei probabilităților.",exercitii:[{"q":"Se aruncă un zar corect. Știind că rezultatul e mai mare ca 3, calculează probabilitatea să fie și număr par.","pasi":["Notăm A=„număr par”={2,4,6} și B=„mai mare ca 3”={4,5,6}.","Intersecția A∩B={4,6}, deci P(A∩B)=2/6.","P(B)=3/6, iar formula dă P(A|B)=P(A∩B)/P(B)=(2/6)/(3/6)=2/3."],"r":"✓ P(par|&gt;3) = <strong>2/3</strong>"},{"q":"Se știe P(A|B)=0.6 și P(B)=0.4. Calculează P(A∩B).","pasi":["Din definiție, P(A|B)=P(A∩B)/P(B), deci P(A∩B)=P(A|B)×P(B).","Înlocuim: P(A∩B)=0.6×0.4.","Calculăm: 0.6×0.4=0.24."],"r":"✓ P(A∩B)=<strong>0.24</strong>"},{"q":"P(A)=0.4, P(B)=0.5, P(A∩B)=0.2. Calculează P(A|B) și observă ce caz special apare.","pasi":["Aplicăm formula: P(A|B)=P(A∩B)/P(B)=0.2/0.5.","Calculăm: 0.2/0.5=0.4.","Observăm că P(A|B)=0.4=P(A): a ști că B s-a produs nu schimbă deloc probabilitatea lui A - acesta e cazul special al independenței."],"r":"✓ P(A|B)=<strong>0.4</strong> = P(A) - A și B sunt independente"},{"q":"Adevărat sau fals: P(A|B) este întotdeauna egal cu P(B|A).","pasi":["Fals - e o confuzie foarte des întâlnită.","Exemplu: într-un pachet de 52 cărți, 26 sunt roșii și 4 sunt ași (2 ași roșii). P(as|roșu)=2/26=1/13≈7.7%.","În schimb P(roșu|as)=2/4=0.5=50%. Cele două probabilități condiționate sunt complet diferite."],"r":"✓ <strong>Fals</strong> - P(A|B) și P(B|A) pot fi foarte diferite"},{"q":"Într-o clasă de 30 de elevi sunt 18 fete și 12 băieți. Dintre fete, 6 poartă ochelari; dintre băieți, 3 poartă ochelari. Alegi la întâmplare un elev care poartă ochelari. Ce probabilitate există să fie fată?","pasi":["Numărul total de elevi cu ochelari e 6 (fete) + 3 (băieți) = 9.","Dintre aceștia, 6 sunt fete, deci evenimentele favorabile sunt 6 din cei 9 cu ochelari.","P(fată|ochelari)=6/9=2/3."],"r":"✓ P(fată|ochelari) = <strong>2/3 ≈ 66.7%</strong>"}]};
CONTINUT_PROBABILITATE["distributia-binomiala"]={definitie:"<div class=\"def-box\"><strong>Definiție:</strong> X~B(n,p) numără succesele în n probe Bernoulli iid, fiecare cu probabilitate p de succes.</div>",formula_display:"P(X=k) = C(n,k)·pᵏ·(1-p)ⁿ⁻ᵏ",diagrama:"<svg viewBox=\"0 0 300 180\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><text x=\"135\" y=\"15\" text-anchor=\"middle\" font-size=\"11\" fill=\"#555\" font-style=\"italic\">P(X=k), n=6, p=0.5</text><line x1=\"15\" y1=\"150\" x2=\"250\" y2=\"150\" stroke=\"#1a1510\" stroke-width=\"1.5\"/><rect x=\"20\" y=\"144\" width=\"28\" height=\"6\" fill=\"#b06000\"/><rect x=\"52\" y=\"114\" width=\"28\" height=\"36\" fill=\"#b06000\"/><rect x=\"84\" y=\"60\" width=\"28\" height=\"90\" fill=\"#b06000\"/><rect x=\"116\" y=\"30\" width=\"28\" height=\"120\" fill=\"#c8922a\"/><rect x=\"148\" y=\"60\" width=\"28\" height=\"90\" fill=\"#b06000\"/><rect x=\"180\" y=\"114\" width=\"28\" height=\"36\" fill=\"#b06000\"/><rect x=\"212\" y=\"144\" width=\"28\" height=\"6\" fill=\"#b06000\"/><text x=\"34\" y=\"163\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">0</text><text x=\"66\" y=\"163\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">1</text><text x=\"98\" y=\"163\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">2</text><text x=\"130\" y=\"163\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">3</text><text x=\"162\" y=\"163\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">4</text><text x=\"194\" y=\"163\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">5</text><text x=\"226\" y=\"163\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">6</text></svg>",intuitiv_text:"Arunci o monedă de 6 ori și numeri de câte ori a picat cap. Uneori ai 0 capete, alteori 6, dar cel mai des ai în jur de 3. <span class=\"hl\">Distribuția binomială numără câte „succese” (de exemplu capete) obții din mai multe încercări la fel, independente</span> - ca un joc repetat de mai multe ori la rând.",intuitiv_nota:"Jacob Bernoulli a studiat-o încă din 1713. Astăzi apare peste tot: în controlul calității, în sondajele electorale, în biologie, la proporțiile de animale cu o anumită caracteristică.",exercitii:[{"q":"O monedă corectă e aruncată de 6 ori. Calculează probabilitatea de a obține exact 3 capete.","pasi":["Folosim formula binomială cu n=6, k=3, p=0.5: P(X=3)=C(6,3)×0.5³×0.5³.","C(6,3)=20, numărul de moduri de a alege care 3 din cele 6 aruncări sunt capete.","Calculăm: P(X=3)=20×(1/8)×(1/8)=20/64=5/16."],"r":"✓ P=<strong>5/16 ≈ 31.25%</strong>"},{"q":"X~B(n,p) cu n=20 aruncări și media E[X]=4. Găsește probabilitatea de succes p.","pasi":["Formula mediei e E[X]=np.","Înlocuim: 4=20×p.","Rezolvăm: p=4/20=0.2."],"r":"✓ p=<strong>0.2</strong>"},{"q":"Dacă p=1 (succesul e garantat de fiecare dată), care e P(X=n) pentru X~B(n,p)?","pasi":["Cu p=1, fiecare din cele n încercări are succes sigur.","P(X=n)=C(n,n)×1ⁿ×0⁰=1.","E cazul-limită în care distribuția binomială devine „deterministă”: X ia mereu exact valoarea n."],"r":"✓ P(X=n)=<strong>1</strong>, cu certitudine"},{"q":"Adevărat sau fals: pentru n fix, distribuția binomială este întotdeauna simetrică, indiferent de p.","pasi":["Fals.","Distribuția binomială e simetrică doar când p=0.5 (succesul și eșecul sunt la fel de probabile).","Pentru p≠0.5, de exemplu p=0.1, bara cea mai înaltă se deplasează spre un capăt și forma nu mai e simetrică."],"r":"✓ <strong>Fals</strong> - simetria apare doar la p=0.5"},{"q":"Într-un lot de piese, 10% sunt defecte. Alegi 5 piese la întâmplare, independent unele de altele. Care e probabilitatea ca exact 1 piesă să fie defectă?","pasi":["Modelăm cu X~B(5,0.1): n=5 piese, p=0.1 probabilitatea ca o piesă să fie defectă.","P(X=1)=C(5,1)×0.1¹×0.9⁴.","Calculăm: C(5,1)=5, 0.9⁴=0.6561, deci P=5×0.1×0.6561=0.32805."],"r":"✓ P ≈ <strong>32.8%</strong>"}]};
CONTINUT_PROBABILITATE["distributia-poisson"]={definitie:"<div class=\"def-box\"><strong>Definiție:</strong> X~Poisson(λ) modelează numărul de evenimente rare într-un interval fix, cu rata medie λ.</div>",formula_display:"P(X=k) = e^(-λ)·λᵏ/k!",diagrama:"<svg viewBox=\"0 0 300 180\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><text x=\"150\" y=\"15\" text-anchor=\"middle\" font-size=\"11\" fill=\"#555\" font-style=\"italic\">P(X=k), λ=3</text><line x1=\"10\" y1=\"150\" x2=\"285\" y2=\"150\" stroke=\"#1a1510\" stroke-width=\"1.5\"/><rect x=\"15\" y=\"123\" width=\"26\" height=\"27\" fill=\"#b06000\"/><rect x=\"45\" y=\"70\" width=\"26\" height=\"80\" fill=\"#b06000\"/><rect x=\"75\" y=\"30\" width=\"26\" height=\"120\" fill=\"#c8922a\"/><rect x=\"105\" y=\"30\" width=\"26\" height=\"120\" fill=\"#c8922a\"/><rect x=\"135\" y=\"60\" width=\"26\" height=\"90\" fill=\"#b06000\"/><rect x=\"165\" y=\"96\" width=\"26\" height=\"54\" fill=\"#b06000\"/><rect x=\"195\" y=\"123\" width=\"26\" height=\"27\" fill=\"#b06000\"/><rect x=\"225\" y=\"138\" width=\"26\" height=\"12\" fill=\"#b06000\"/><rect x=\"255\" y=\"146\" width=\"26\" height=\"4\" fill=\"#b06000\"/><text x=\"28\" y=\"163\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">0</text><text x=\"58\" y=\"163\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">1</text><text x=\"88\" y=\"163\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">2</text><text x=\"118\" y=\"163\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">3</text><text x=\"148\" y=\"163\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">4</text><text x=\"178\" y=\"163\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">5</text><text x=\"208\" y=\"163\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">6</text><text x=\"238\" y=\"163\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">7</text><text x=\"268\" y=\"163\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">8</text></svg>",intuitiv_text:"Un pescar prinde în medie 3 pești pe oră, dar unele ore prinde 0, altele 5 sau 6. <span class=\"hl\">Distribuția Poisson numără câte evenimente rare se întâmplă într-un interval de timp fix</span>, când acestea apar la întâmplare, unul independent de altul - ca numărul de apeluri telefonice într-un minut sau numărul de stele căzătoare într-o oră.",intuitiv_nota:"Siméon Denis Poisson a introdus-o în 1837, ca limită a distribuției binomiale B(n,p) atunci când n→∞, p→0, iar np rămâne constant, egal cu λ.",exercitii:[{"q":"La o centrală telefonică sosesc în medie λ=3 apeluri pe minut, modelate ca X~Poisson(3). Calculează probabilitatea să nu sosească niciun apel într-un minut.","pasi":["Formula Poisson e P(X=k)=e^(-λ)×λᵏ/k!.","Pentru k=0: P(X=0)=e^(-3)×3⁰/0!=e^(-3)×1/1.","Calculăm: e^(-3)≈0.0498."],"r":"✓ P(X=0) ≈ <strong>4.98%</strong>"},{"q":"Pentru X~Poisson(λ) se știe că P(X=0)=0.2231. Găsește λ.","pasi":["Din formulă, P(X=0)=e^(-λ)×λ⁰/0!=e^(-λ).","Punem e^(-λ)=0.2231 și logaritmăm: -λ=ln(0.2231).","Calculăm: ln(0.2231)≈-1.5, deci λ=1.5."],"r":"✓ λ=<strong>1.5</strong>"},{"q":"Pentru λ foarte mic, de exemplu λ=0.1 (evenimente foarte rare), unde se concentrează majoritatea probabilității?","pasi":["Calculăm P(X=0)=e^(-0.1)×0.1⁰/0!=e^(-0.1).","e^(-0.1)≈0.9048.","Aproape toată probabilitatea, peste 90%, se află la k=0: când evenimentele sunt foarte rare, cel mai probabil scenariu e „niciunul”."],"r":"✓ P(X=0) ≈ <strong>90.5%</strong> - cazul-limită λ→0 concentrează totul în k=0"},{"q":"Adevărat sau fals: pentru distribuția Poisson, media și varianța sunt întotdeauna egale.","pasi":["Adevărat.","Pentru X~Poisson(λ), atât E[X] cât și Var(X) sunt egale cu λ.","E o proprietate specială, unică pentru distribuția Poisson - o poți folosi ca test rapid dacă niște date par a fi Poisson."],"r":"✓ <strong>Adevărat</strong> - E[X]=Var(X)=λ"},{"q":"La o centrală telefonică sosesc în medie 4 apeluri pe minut. Care e probabilitatea să nu sosească niciun apel într-un interval de 30 de secunde?","pasi":["Rata pentru 30 de secunde (jumătate de minut) e λ=4×0.5=2 apeluri.","Aplicăm formula: P(X=0)=e^(-2)×2⁰/0!=e^(-2).","Calculăm: e^(-2)≈0.1353."],"r":"✓ P(X=0) ≈ <strong>13.53%</strong>"}]};
CONTINUT_PROBABILITATE["entropia-shannon"]={definitie:"<div class=\"def-box\"><strong>Definiție:</strong> Entropia Shannon H(X) măsoară cantitatea medie de informație (incertitudine) a sursei discrete X cu distribuție p(x).</div>",formula_display:"H(X) = -∑ p(x)·log₂p(x) [biți]",diagrama:"<svg viewBox=\"0 0 320 180\" xmlns=\"http://www.w3.org/2000/svg\" width=\"320\"><line x1=\"30\" y1=\"150\" x2=\"290\" y2=\"150\" stroke=\"#1a1510\" stroke-width=\"1.5\"/><line x1=\"30\" y1=\"20\" x2=\"30\" y2=\"150\" stroke=\"#1a1510\" stroke-width=\"1.5\"/><path d=\"M30,150 L56,94 L82,63 L108,44 L134,34 L160,30 L186,34 L212,44 L238,63 L264,94 L290,150\" fill=\"none\" stroke=\"#b06000\" stroke-width=\"2.5\"/><circle cx=\"160\" cy=\"30\" r=\"4\" fill=\"#c8922a\"/><text x=\"160\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#a87418\">H=1 bit (p=0.5)</text><text x=\"30\" y=\"164\" font-size=\"10\" fill=\"#555\">0</text><text x=\"160\" y=\"164\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">0.5</text><text x=\"285\" y=\"164\" text-anchor=\"end\" font-size=\"10\" fill=\"#555\">1</text><text x=\"295\" y=\"153\" font-size=\"12\" fill=\"#555\" font-style=\"italic\">p</text><text x=\"12\" y=\"90\" font-size=\"11\" fill=\"#555\" font-style=\"italic\" transform=\"rotate(-90 12 90)\">H(p)</text></svg>",intuitiv_text:"Dacă te joci „ghicește ce am în mână” cu o monedă trucată care iese aproape mereu cap, poți ghici ușor - nu ai nevoie de multe întrebări. Dar dacă moneda e corectă, jumătate-jumătate, nu ai niciun indiciu și trebuie să întrebi cât poți de mult. <span class=\"hl\">Entropia Shannon măsoară cât de „surprinzător” sau greu de ghicit este un rezultat</span> - cu cât mai multă nesiguranță, cu atât entropia e mai mare.",intuitiv_nota:"Claude Shannon (1948) a fondat teoria informației. Entropia e maximizată de distribuția uniformă și minimizată (=0) de sursa deterministă.",exercitii:[{"q":"O monedă corectă are P(cap)=P(pajură)=0.5. Calculează entropia Shannon H a acestei surse.","pasi":["Formula e H=-∑p(x)log₂p(x), cu două rezultate posibile, fiecare cu probabilitate 0.5.","H=-0.5×log₂(0.5)-0.5×log₂(0.5).","log₂(0.5)=-1, deci H=-0.5×(-1)-0.5×(-1)=0.5+0.5=1."],"r":"✓ H=<strong>1 bit</strong> - incertitudinea maximă posibilă pentru 2 rezultate"},{"q":"O sursă binară cu P(0)=p are entropia H=0.7219 biți. Arată că atât p=0.2 cât și p=0.8 produc această valoare.","pasi":["Pentru p=0.8: H=-0.8×log₂(0.8)-0.2×log₂(0.2).","log₂(0.8)≈-0.3219 și log₂(0.2)≈-2.3219, deci H≈-0.8×(-0.3219)-0.2×(-2.3219)=0.2575+0.4644=0.7219.","Pentru p=0.2 calculul e identic, doar termenii își schimbă locul - formula e simetrică față de p=0.5, deci ambele valori dau aceeași entropie."],"r":"✓ Ambele: H(0.2)=H(0.8)=<strong>0.7219 biți</strong> (simetrie)"},{"q":"O sursă are P(0)=1, adică rezultatul e mereu 0, cu certitudine. Calculează entropia H.","pasi":["Formula e H=-∑p(x)log₂p(x); aici avem un singur termen, cu p=1.","H=-1×log₂(1).","Cum log₂(1)=0, obținem H=-1×0=0."],"r":"✓ H=<strong>0 biți</strong> - o sursă complet sigură nu are nicio incertitudine"},{"q":"De ce în formula entropiei apare termenul log₂(1/p), adică -log₂p, și nu de exemplu -log₂(1-p)?","pasi":["Termenul log₂(1/p) se numește „informația” (sau „surpriza”) evenimentului cu probabilitate p: cu cât p e mai mic, cu atât log₂(1/p) e mai mare.","Are sens: aflarea unui eveniment rar ne surprinde mai mult și ne dă mai multă informație decât aflarea unuia obișnuit.","Entropia H e exact media acestei informații, ponderată cu probabilitatea fiecărui rezultat: H=∑p(x)×log₂(1/p(x))."],"r":"✓ <strong>log₂(1/p) este informația evenimentului</strong>; H e media ei"},{"q":"Un alfabet jucărie are 4 simboluri, fiecare la fel de probabil (P=0.25 pentru fiecare). Calculează entropia sursei și explică ce înseamnă practic acest număr.","pasi":["Formula: H=-∑p(x)log₂p(x), cu 4 termeni identici, fiecare cu p=0.25.","H=-4×0.25×log₂(0.25).","log₂(0.25)=-2, deci H=-4×0.25×(-2)=4×0.5=2."],"r":"✓ H=<strong>2 biți</strong> - în medie ai nevoie de exact 2 biți pentru a codifica fiecare simbol"}]};
CONTINUT_PROBABILITATE["inegalitatea-lui-markov"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Dacă X≥0 v.a. cu E[X] finit, atunci probabilitatea că X depășește un prag a este mărginită superior de E[X]/a.</div>",formula_display:"P(X ≥ a) ≤ E[X] / a pentru orice a&gt;0",diagrama:"<svg viewBox=\"0 0 320 180\" xmlns=\"http://www.w3.org/2000/svg\" width=\"320\"><line x1=\"25\" y1=\"150\" x2=\"300\" y2=\"150\" stroke=\"#1a1510\" stroke-width=\"1.5\"/><path d=\"M28,150 C45,150 40,38 65,32 C95,25 105,95 135,115 C175,138 225,146 265,149 C280,150 292,150 298,150\" fill=\"rgba(176,96,0,0.12)\" stroke=\"#b06000\" stroke-width=\"2\"/><line x1=\"185\" y1=\"25\" x2=\"185\" y2=\"150\" stroke=\"#c8922a\" stroke-width=\"1.5\" stroke-dasharray=\"4,4\"/><text x=\"185\" y=\"18\" text-anchor=\"middle\" font-size=\"12\" fill=\"#a87418\">a</text><text x=\"245\" y=\"132\" font-size=\"11\" fill=\"#7a4400\" font-style=\"italic\">coadă</text><text x=\"162\" y=\"168\" text-anchor=\"middle\" font-size=\"12\" fill=\"#555\" font-style=\"italic\">P(X≥a) ≤ E[X]/a</text></svg>",intuitiv_text:"Dacă majoritatea copiilor dintr-o clasă au puține bomboane, dar câțiva au foarte multe, media bomboanelor pe copil rămâne totuși mică. <span class=\"hl\">Dacă media este mică, nu prea mulți copii pot avea foarte multe bomboane</span> - altfel media ar fi mult mai mare. Inegalitatea lui Markov transformă exact această idee simplă într-o formulă.",intuitiv_nota:"Andrei Markov a formulat-o în 1884. E cea mai simplă inegalitate probabilistică și, aplicată variabilei (X-μ)², dă chiar inegalitatea lui Cebîșev.",exercitii:[{"q":"O variabilă aleatoare X≥0 are media E[X]=4. Calculează un majorant pentru P(X≥20) folosind inegalitatea lui Markov.","pasi":["Formula lui Markov: P(X≥a) ≤ E[X]/a, valabilă pentru orice a&gt;0.","Înlocuim a=20 și E[X]=4: P(X≥20) ≤ 4/20.","Calculăm: 4/20=1/5=0.2."],"r":"✓ ≤<strong>20%</strong>"},{"q":"Se știe E[X]=5 și se dorește P(X≥a)≤0.1. Care e cea mai mică valoare a lui a care garantează acest lucru?","pasi":["Pornim de la Markov: P(X≥a) ≤ E[X]/a = 5/a.","Punem condiția 5/a ≤ 0.1.","Rezolvăm: a ≥ 5/0.1 = 50."],"r":"✓ a ≥ <strong>50</strong>"},{"q":"E[X]=10. Ce spune inegalitatea lui Markov despre P(X≥5), adică atunci când pragul a e mai mic decât media?","pasi":["Aplicăm formula: P(X≥5) ≤ E[X]/5=10/5=2.","Dar orice probabilitate e oricum ≤1, deci majorantul „2” nu adaugă nicio informație utilă.","Acesta e cazul-limită în care Markov devine banală: e informativă doar când a&gt;E[X]."],"r":"✓ Majorant <strong>2 (inutil)</strong> - inegalitatea e banală când a≤E[X]"},{"q":"Cum se poate deduce inegalitatea lui Cebîșev din inegalitatea lui Markov?","pasi":["Aplicăm Markov nu lui X, ci variabilei nenegative Y=(X-μ)², cu pragul a=(kσ)².","Markov dă P(Y≥(kσ)²) ≤ E[Y]/(kσ)² = σ²/(k²σ²) = 1/k².","Dar P(Y≥(kσ)²) este exact P(|X-μ|≥kσ) - deci am obținut exact inegalitatea lui Cebîșev."],"r":"✓ <strong>Cebîșev se deduce din Markov</strong>, aplicat lui (X-μ)²"},{"q":"Venitul mediu lunar într-un oraș e de 3000 RON. Folosind Markov, estimează un majorant pentru procentul de locuitori care câștigă peste 15000 RON pe lună.","pasi":["Notăm X=venitul lunar, cu E[X]=3000 RON, iar pragul a=15000 RON.","Aplicăm Markov: P(X≥15000) ≤ E[X]/a = 3000/15000.","Calculăm: 3000/15000=1/5=0.2."],"r":"✓ ≤<strong>20%</strong> din locuitori"}]};
CONTINUT_PROBABILITATE["teorema-lui-de-moivre-laplace"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Dacă X~B(n,p), atunci pentru n mare distribuția lui X se aproximează bine cu distribuția normală N(np, np(1−p)).</div>",formula_display:"B(n,p) ≈ N(np, np(1−p)) pentru n mare",diagrama:"<svg viewBox=\"0 0 300 180\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><text x=\"150\" y=\"15\" text-anchor=\"middle\" font-size=\"11\" fill=\"#555\" font-style=\"italic\">B(n,p) ≈ N(np, np(1-p))</text><line x1=\"10\" y1=\"150\" x2=\"260\" y2=\"150\" stroke=\"#1a1510\" stroke-width=\"1.5\"/><rect x=\"15\" y=\"148\" width=\"24\" height=\"2\" fill=\"rgba(176,96,0,0.4)\"/><rect x=\"42\" y=\"136\" width=\"24\" height=\"14\" fill=\"rgba(176,96,0,0.4)\"/><rect x=\"69\" y=\"102\" width=\"24\" height=\"48\" fill=\"rgba(176,96,0,0.4)\"/><rect x=\"96\" y=\"54\" width=\"24\" height=\"96\" fill=\"rgba(176,96,0,0.4)\"/><rect x=\"123\" y=\"30\" width=\"24\" height=\"120\" fill=\"rgba(176,96,0,0.4)\"/><rect x=\"150\" y=\"54\" width=\"24\" height=\"96\" fill=\"rgba(176,96,0,0.4)\"/><rect x=\"177\" y=\"102\" width=\"24\" height=\"48\" fill=\"rgba(176,96,0,0.4)\"/><rect x=\"204\" y=\"136\" width=\"24\" height=\"14\" fill=\"rgba(176,96,0,0.4)\"/><rect x=\"231\" y=\"148\" width=\"24\" height=\"2\" fill=\"rgba(176,96,0,0.4)\"/><path d=\"M15,148 C50,145 70,50 135,30 C200,50 220,145 255,148\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"2.5\"/></svg>",intuitiv_text:"Dacă arunci o monedă de foarte multe ori și numeri de câte ori a picat cap, rezultatele posibile - desenate ca o scară de bare - încep să semene tot mai mult cu un deal neted, în formă de clopot. <span class=\"hl\">Pentru multe aruncări, „scara” de bare a distribuției binomiale devine practic un clopot neted</span> - de-asta putem folosi formule mai simple, ale distribuției normale, în loc să numărăm fiecare bară.",intuitiv_nota:"Abraham de Moivre a demonstrat cazul p=1/2 în 1733, iar Pierre-Simon Laplace l-a generalizat pentru p oarecare în 1812 - practic primul rezultat de tip „teoremă centrală limită” din istorie, cu 170 de ani înaintea formei generale.",exercitii:[{"q":"O monedă corectă e aruncată de 100 ori. Folosind aproximarea normală, calculează probabilitatea ca numărul de capete să fie între 55 și 65 (P(55≤X≤65)).","pasi":["Parametrii aproximării: μ=np=100×0.5=50, σ²=np(1-p)=100×0.5×0.5=25, deci σ=5.","Standardizăm capetele intervalului: Z₁=(55-50)/5=1 și Z₂=(65-50)/5=3.","Din tabelul normal: P(1&lt;Z&lt;3)=Φ(3)-Φ(1)=0.9987-0.8413=0.1574."],"r":"✓ ≈<strong>15.74%</strong>"},{"q":"Câte aruncări n ale unei monede corecte (p=0.5) sunt necesare pentru ca deviația standard a numărului de capete, σ=√(np(1-p)), să fie cel puțin 20?","pasi":["Punem condiția √(n×0.5×0.5)≥20, adică √(0.25n)≥20.","Ridicăm la pătrat: 0.25n≥400.","Rezolvăm: n≥400/0.25=1600."],"r":"✓ n ≥ <strong>1600</strong> aruncări"},{"q":"Pentru ce valori ale lui n și p este considerată valabilă aproximarea normală a distribuției binomiale?","pasi":["Aproximarea funcționează bine doar când distribuția nu e prea „strâmbă”, adică nici p, nici 1-p nu sunt prea aproape de 0.","Regula empirică uzuală cere np≥5 și n(1-p)≥5 (unii autori cer chiar ≥10, pentru precizie mai bună).","Acesta e cazul-limită al teoremei: sub aceste praguri aproximarea normală devine nesigură și trebuie folosită distribuția binomială exactă."],"r":"✓ <strong>np≥5 și n(1−p)≥5</strong>, aproximativ"},{"q":"Ce relație are teorema De Moivre–Laplace cu teorema centrală limită (TCL)?","pasi":["X~B(n,p) este suma a n variabile Bernoulli(p) independente și identic distribuite.","TCL spune că suma a n variabile iid, standardizată, converge la o distribuție normală când n crește.","Aplicând TCL acestei sume obținem chiar enunțul teoremei De Moivre–Laplace."],"r":"✓ Este <strong>cazul particular al TCL pentru variabile Bernoulli</strong>"},{"q":"Într-un sondaj, 30% dintre alegători susțin un candidat. Se intervievează 1000 de persoane la întâmplare. Aproximează probabilitatea ca mai mult de 320 dintre ele să susțină candidatul.","pasi":["Parametrii aproximării: μ=np=1000×0.3=300, σ²=np(1-p)=1000×0.3×0.7=210, deci σ=√210≈14.49.","Standardizăm: Z=(320-300)/14.49≈1.38.","Din tabelul normal: P(Z&gt;1.38)≈1-0.9162=0.0838."],"r":"✓ ≈<strong>8.38%</strong>"}]};
CONTINUT_PROBABILITATE["inegalitatea-lui-jensen"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Dacă φ este o funcție convexă și X o variabilă aleatoare cu medie finită, atunci valoarea lui φ în medie este cel mult media valorilor lui φ.</div>",formula_display:"φ(E[X]) ≤ E[φ(X)] (φ convexă)",diagrama:"<svg viewBox=\"0 0 300 180\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><line x1=\"20\" y1=\"160\" x2=\"280\" y2=\"160\" stroke=\"#1a1510\" stroke-width=\"1.5\"/><path d=\"M50,55 Q165,175 280,55\" fill=\"none\" stroke=\"#b06000\" stroke-width=\"2.5\"/><line x1=\"107\" y1=\"100\" x2=\"223\" y2=\"100\" stroke=\"#c8922a\" stroke-width=\"2\" stroke-dasharray=\"4,4\"/><circle cx=\"107\" cy=\"100\" r=\"4\" fill=\"#b06000\"/><circle cx=\"223\" cy=\"100\" r=\"4\" fill=\"#b06000\"/><line x1=\"165\" y1=\"100\" x2=\"165\" y2=\"115\" stroke=\"#7a4400\" stroke-width=\"1.5\"/><circle cx=\"165\" cy=\"100\" r=\"4\" fill=\"#c8922a\"/><circle cx=\"165\" cy=\"115\" r=\"4\" fill=\"#b06000\"/><text x=\"165\" y=\"90\" text-anchor=\"middle\" font-size=\"11\" fill=\"#a87418\">E[φ(X)]</text><text x=\"165\" y=\"132\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7a4400\">φ(E[X])</text><text x=\"150\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#555\" font-style=\"italic\">φ convexă: coarda stă deasupra curbei</text></svg>",intuitiv_text:"Imaginează-ți un bol rotund, ca o farfurie adâncă. Dacă pui degetul pe marginea bolului într-un loc și tragi o sforicică dreaptă până în alt loc de pe margine, sfoara stă mereu deasupra fundului bolului, niciodată pe dedesubt. <span class=\"hl\">La fel se întâmplă cu o funcție „în formă de bol” (convexă): calculată chiar în mijloc, ea dă o valoare mai mică decât media calculelor făcute în fiecare punct.</span> Dacă bolul ar fi întors cu gura în jos (funcție concavă), totul s-ar inversa.",intuitiv_nota:"Johan Jensen a publicat-o în 1906. Generalizează inegalitatea mediei aritmetice și geometrice și stă la baza multor rezultate din statistică, teoria informației și optimizare - de exemplu, faptul că entropia e concavă.",exercitii:[{"q":"O variabilă X ia valoarea 1 cu probabilitate 1/2 și valoarea 5 cu probabilitate 1/2. Folosind funcția convexă φ(x)=x², verifică inegalitatea lui Jensen.","pasi":["Calculăm mai întâi media lui X: E[X] = 1×0.5 + 5×0.5 = 3.","Aplicăm funcția în medie: φ(E[X]) = φ(3) = 3² = 9.","Acum calculăm media funcției: E[φ(X)] = 1²×0.5 + 5²×0.5 = 0.5 + 12.5 = 13."],"r":"✓ 9 ≤ <strong>13</strong>, inegalitatea lui Jensen se verifică"},{"q":"Pentru o variabilă aleatoare X și o funcție φ se știe că φ(E[X]) = 5, iar E[φ(X)] = 3. Ce poți deduce despre forma funcției φ?","pasi":["Inegalitatea lui Jensen pentru o funcție convexă cere φ(E[X]) ≤ E[φ(X)], adică valoarea calculată în medie trebuie să fie cea mai mică.","Aici avem exact situația inversă: 5 este mai mare decât 3, deci φ(E[X]) depășește E[φ(X)].","Această ordine corespunde cazului în care φ este concavă, pentru care inegalitatea lui Jensen se inversează: φ(E[X]) ≥ E[φ(X)]."],"r":"✓ φ este (pe acest exemplu) <strong>concavă</strong>, nu convexă"},{"q":"X este o variabilă „constantă”: ia mereu valoarea 4, cu probabilitate 1. Ce se întâmplă cu inegalitatea lui Jensen în acest caz, pentru φ(x)=x²?","pasi":["Media lui X este chiar valoarea ei constantă: E[X] = 4.","Calculăm φ(E[X]) = φ(4) = 16.","Cum X ia mereu aceeași valoare, și φ(X) ia mereu aceeași valoare, deci E[φ(X)] = φ(4) = 16."],"r":"✓ φ(E[X]) = E[φ(X)] = <strong>16</strong>: când nu există împrăștiere, inegalitatea devine egalitate"},{"q":"Adevărat sau fals: inegalitatea φ(E[X]) ≤ E[φ(X)] este valabilă pentru orice funcție φ, indiferent dacă aceasta este convexă sau nu.","pasi":["Fals. Inegalitatea lui Jensen, în această formă, este garantată doar pentru funcții convexe.","De exemplu, pentru φ(x)=√x, care este concavă, relația se inversează: φ(E[X]) ≥ E[φ(X)].","Deci forma funcției (bol cu gura în sus sau în jos) decide sensul inegalității."],"r":"✓ <strong>Fals</strong> - direcția depinde de convexitatea sau concavitatea lui φ"},{"q":"La un joc de noroc simplu, un jucător câștigă fie 2 lei, fie 8 lei, cu șanse egale. Folosind φ(x)=x², compară media pătratelor câștigurilor cu pătratul mediei câștigurilor.","pasi":["Media câștigurilor este E[X] = 2×0.5 + 8×0.5 = 5 lei.","Pătratul mediei este φ(E[X]) = 5² = 25.","Media pătratelor este E[X²] = 2²×0.5 + 8²×0.5 = 2 + 32 = 34."],"r":"✓ 25 ≤ <strong>34</strong>: media pătratelor depășește pătratul mediei, exact cum prezice Jensen pentru φ convexă"}]};
CONTINUT_PROBABILITATE["distributia-exponentiala"]={definitie:"<div class=\"def-box\"><strong>Definiție:</strong> X~Exp(λ) modelează timpul de așteptare până la producerea unui eveniment rar, cu rata λ&gt;0 și densitate f(x)=λe^(−λx) pentru x≥0.</div>",formula_display:"f(x) = λe^(−λx), x≥0 (E[X]=1/λ, Var(X)=1/λ²)",diagrama:"<svg viewBox=\"0 0 300 180\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><line x1=\"20\" y1=\"150\" x2=\"290\" y2=\"150\" stroke=\"#1a1510\" stroke-width=\"1.5\"/><line x1=\"20\" y1=\"150\" x2=\"20\" y2=\"20\" stroke=\"#1a1510\" stroke-width=\"1.5\"/><path d=\"M22,28 C45,110 65,140 100,147 C150,152 200,150 285,150 L22,150 Z\" fill=\"rgba(176,96,0,0.12)\" stroke=\"#b06000\" stroke-width=\"2.5\"/><line x1=\"100\" y1=\"147\" x2=\"100\" y2=\"20\" stroke=\"#c8922a\" stroke-width=\"1.5\" stroke-dasharray=\"4,4\"/><line x1=\"170\" y1=\"150\" x2=\"170\" y2=\"20\" stroke=\"#c8922a\" stroke-width=\"1.5\" stroke-dasharray=\"4,4\"/><text x=\"100\" y=\"16\" text-anchor=\"middle\" font-size=\"11\" fill=\"#a87418\">s</text><text x=\"170\" y=\"16\" text-anchor=\"middle\" font-size=\"11\" fill=\"#a87418\">s+t</text><text x=\"150\" y=\"168\" text-anchor=\"middle\" font-size=\"11\" fill=\"#555\" font-style=\"italic\">coada de după s arată la fel ca la început</text></svg>",intuitiv_text:"Aștepți să sune telefonul sau să vină autobuzul. <span class=\"hl\">Distribuția exponențială spune că, dacă evenimentul nu s-a întâmplat încă, nu contează deloc cât ai așteptat deja - șansa de a mai aștepta un minut e mereu aceeași.</span> E ca și cum timpul „uită” tot ce s-a întâmplat până acum: nu ești nici mai norocos, nici mai ghinionist pentru că ai așteptat deja mult.",intuitiv_nota:"A fost formalizată în secolul XX, în teoria proceselor Poisson, și modelează durata de viață a componentelor electronice, timpul dintre dezintegrări radioactive sau timpul de așteptare la un ghișeu.",exercitii:[{"q":"Timpul de așteptare pentru un mesaj urmează Exp(λ=0.2) (mesaje pe minut). Care este timpul mediu de așteptare?","pasi":["Formula spune că media distribuției exponențiale este E[X] = 1/λ.","Înlocuim λ=0.2: E[X] = 1/0.2 = 5."],"r":"✓ E[X] = <strong>5 minute</strong>"},{"q":"Se știe că media timpului de așteptare la un ghișeu este de 4 minute. Care este rata λ a distribuției exponențiale?","pasi":["Pornim de la relația E[X] = 1/λ și o inversăm: λ = 1/E[X].","Înlocuim E[X]=4: λ = 1/4 = 0.25."],"r":"✓ λ = <strong>0.25 evenimente/minut</strong>"},{"q":"Ce se întâmplă cu probabilitatea P(X&gt;x) atunci când rata λ devine foarte mare, adică evenimentul e „nerăbdător” și tinde să se producă aproape imediat?","pasi":["Formula probabilității de a aștepta mai mult decât x este P(X&gt;x) = e^(−λx).","Dacă λ crește foarte mult, exponentul −λx devine tot mai negativ pentru orice x&gt;0 fixat, deci e^(−λx) se apropie de 0.","Practic, cu o rată uriașă, evenimentul se întâmplă aproape instantaneu, deci șansa de a mai aștepta orice interval x&gt;0 devine neglijabilă."],"r":"✓ P(X&gt;x) → <strong>0</strong> pe măsură ce λ → ∞"},{"q":"Adevărat sau fals: dacă ai așteptat deja 10 minute pentru autobuz și timpul de așteptare este exponențial, șansa de a mai aștepta încă 5 minute este mai mică decât dacă tocmai ai ajuns la stație.","pasi":["Fals. Proprietatea de lipsă de memorie a distribuției exponențiale spune că trecutul nu contează.","P(mai aștepți 5 minute | ai așteptat deja 10) este exact egală cu P(aștepți 5 minute de la început), indiferent cât ai așteptat deja."],"r":"✓ <strong>Fals</strong> - distribuția exponențială „uită” complet trecutul"},{"q":"O centrală telefonică primește apeluri, iar timpul dintre două apeluri succesive este Exp(λ=3) (apeluri pe minut). Care este probabilitatea ca următorul apel să vină în mai puțin de 20 de secunde?","pasi":["Transformăm 20 de secunde în minute: 20/60 = 1/3 minut.","Folosim formula P(X≤x) = 1 − e^(−λx), cu λ=3 și x=1/3.","Calculăm exponentul: λx = 3 × 1/3 = 1, deci P(X≤1/3) = 1 − e^(−1) ≈ 1 − 0.3679 = 0.6321."],"r":"✓ ≈<strong>63.21%</strong> șansă ca următorul apel să vină în sub 20 de secunde"}]};
CONTINUT_PROBABILITATE["teorema-lui-borel-cantelli"]={definitie:"<div class=\"def-box\"><strong>Enunț (prima lemă):</strong> Fie (Aₙ) un șir de evenimente. Dacă suma probabilităților lor este finită, atunci cu probabilitate 1 doar un număr finit dintre ele se produc.</div>",formula_display:"∑P(Aₙ) &lt; ∞ → P(Aₙ se produce infinit de multe ori) = 0",diagrama:"<svg viewBox=\"0 0 320 180\" xmlns=\"http://www.w3.org/2000/svg\" width=\"320\"><text x=\"75\" y=\"15\" text-anchor=\"middle\" font-size=\"11\" fill=\"#555\" font-style=\"italic\">∑P(Aₙ) &lt; ∞</text><line x1=\"15\" y1=\"110\" x2=\"135\" y2=\"110\" stroke=\"#1a1510\" stroke-width=\"1.5\"/><circle cx=\"25\" cy=\"110\" r=\"9\" fill=\"#b06000\"/><circle cx=\"47\" cy=\"110\" r=\"6.5\" fill=\"#b06000\"/><circle cx=\"66\" cy=\"110\" r=\"4.5\" fill=\"#b06000\"/><circle cx=\"82\" cy=\"110\" r=\"3\" fill=\"#b06000\"/><circle cx=\"96\" cy=\"110\" r=\"1.8\" fill=\"#b06000\"/><circle cx=\"108\" cy=\"110\" r=\"1\" fill=\"#b06000\" opacity=\"0.4\"/><text x=\"75\" y=\"132\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">Aₙ tot mai rare</text><text x=\"75\" y=\"148\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7a4400\" font-weight=\"600\">doar finit apar</text><text x=\"245\" y=\"15\" text-anchor=\"middle\" font-size=\"11\" fill=\"#555\" font-style=\"italic\">∑P(Aₙ) = ∞ (independente)</text><line x1=\"165\" y1=\"110\" x2=\"305\" y2=\"110\" stroke=\"#1a1510\" stroke-width=\"1.5\"/><circle cx=\"175\" cy=\"110\" r=\"6\" fill=\"#c8922a\"/><circle cx=\"195\" cy=\"110\" r=\"6\" fill=\"#c8922a\"/><circle cx=\"215\" cy=\"110\" r=\"6\" fill=\"#c8922a\"/><circle cx=\"235\" cy=\"110\" r=\"6\" fill=\"#c8922a\"/><circle cx=\"255\" cy=\"110\" r=\"6\" fill=\"#c8922a\"/><circle cx=\"275\" cy=\"110\" r=\"6\" fill=\"#c8922a\"/><circle cx=\"295\" cy=\"110\" r=\"6\" fill=\"#c8922a\"/><text x=\"235\" y=\"148\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7a4400\" font-weight=\"600\">infinit de multe apar</text><line x1=\"150\" y1=\"30\" x2=\"150\" y2=\"160\" stroke=\"#1a1510\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/></svg>",intuitiv_text:"Închipuie-ți că arunci de fiecare dată un zar din ce în ce mai greu de nimerit: prima dată trebuie să ghicești din 6 fețe, a doua oară din 36, a treia oară din 216, și tot așa, tot mai greu, tot mai repede. <span class=\"hl\">Dacă șansele scad suficient de repede, aproape sigur va veni un moment după care nu vei mai nimeri niciodată.</span> Dar dacă, în schimb, arunci mereu aceeași monedă corectă la infinit de multe rânduri, stema va apărea din nou și din nou, la nesfârșit, aproape sigur.",intuitiv_nota:"Émile Borel a demonstrat prima parte în 1909, iar Francesco Cantelli a adăugat-o pe a doua, pentru evenimente independente, în 1917. Împreună, cele două leme sunt un instrument esențial în demonstrarea legii tari a numerelor mari și a altor rezultate de convergență aproape sigură.",exercitii:[{"q":"Fie Aₙ un șir de evenimente cu P(Aₙ)=1/n³. Verifică dacă se poate aplica prima lemă Borel-Cantelli.","pasi":["Prima lemă cere ca suma probabilităților să fie finită: ∑P(Aₙ) = ∑1/n³.","Aceasta este o serie de tip „p” cu p=3, iar seriile de acest tip converg (au sumă finită) atunci când p&gt;1.","Cum p=3 este mai mare decât 1, seria converge, deci suma este finită."],"r":"✓ Suma este <strong>finită</strong> → aproape sigur doar un număr finit de Aₙ se produc"},{"q":"Se știe, dintr-un rezultat aplicat, că prima lemă Borel-Cantelli garantează că, pentru un șir de evenimente Aₙ, doar un număr finit dintre ele se produc. Ce poți spune despre ∑P(Aₙ)?","pasi":["Prima lemă Borel-Cantelli are ca ipoteză exact faptul că ∑P(Aₙ) este finită (seria converge).","Dacă concluzia ei (finit de multe Aₙ se produc) este garantată prin această lemă, înseamnă că ipoteza ei trebuie să fie îndeplinită."],"r":"✓ ∑P(Aₙ) trebuie să fie <strong>finită</strong> (seria converge)"},{"q":"Fie Aₙ un șir de evenimente cu P(Aₙ)=1/n (seria armonică). Se poate aplica prima lemă Borel-Cantelli?","pasi":["Suma ∑1/n este seria armonică, cunoscută ca fiind divergentă (nu are o valoare finită).","Cum ipoteza primei leme (∑P(Aₙ)&lt;∞) nu este îndeplinită, lema nu ne spune nimic în acest caz.","Acesta este exact cazul-limită dintre „converge” și „diverge”: p=1 este granița pentru seriile de tip 1/n^p."],"r":"✓ Prima lemă <strong>nu se aplică</strong> - seria armonică diverge exact la limita p=1"},{"q":"Adevărat sau fals: dacă ∑P(Aₙ) = ∞, atunci evenimentele Aₙ se produc, în mod sigur, de un număr infinit de ori.","pasi":["Fals, în general. A doua lemă Borel-Cantelli, care garantează că Aₙ se produc infinit de des, cere în plus ca evenimentele să fie independente.","Dacă evenimentele nu sunt independente, suma poate diverge fără ca infinit de multe Aₙ să se producă neapărat."],"r":"✓ <strong>Fals</strong> - concluzia „infinit de des” cere și independența evenimentelor"},{"q":"Într-un șir infinit de aruncări independente ale unui zar corect, care e probabilitatea ca fața 6 să apară doar de un număr finit de ori?","pasi":["La fiecare aruncare, șansa să iasă fața 6 este P(Aₙ)=1/6, aceeași la fiecare pas și independentă de aruncările anterioare.","Suma probabilităților este ∑1/6, care diverge (crește la infinit pe măsură ce adunăm tot mai mulți termeni).","Cum evenimentele sunt independente și suma diverge, a doua lemă Borel-Cantelli garantează că fața 6 apare infinit de des, aproape sigur."],"r":"✓ Probabilitatea ca 6 să apară doar finit de multe ori este <strong>0</strong> - practic, apare infinit de des"}]};
CONTINUT_PROBABILITATE["covarianta-si-corelatia"]={definitie:"<div class=\"def-box\"><strong>Definiție:</strong> Covarianța Cov(X,Y)=E[(X−E[X])(Y−E[Y])]=E[XY]−E[X]E[Y] măsoară variația comună a două variabile aleatoare; coeficientul de corelație o normalizează la [−1,1].</div>",formula_display:"ρ(X,Y) = Cov(X,Y) / (σ_X · σ_Y) , −1 ≤ ρ ≤ 1",diagrama:"<svg viewBox=\"0 0 300 200\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><line x1=\"30\" y1=\"20\" x2=\"30\" y2=\"170\" stroke=\"#1a1510\" stroke-width=\"1.5\"/><line x1=\"30\" y1=\"170\" x2=\"290\" y2=\"170\" stroke=\"#1a1510\" stroke-width=\"1.5\"/><line x1=\"160\" y1=\"20\" x2=\"160\" y2=\"170\" stroke=\"#c8922a\" stroke-width=\"1.5\" stroke-dasharray=\"4,4\"/><line x1=\"30\" y1=\"95\" x2=\"290\" y2=\"95\" stroke=\"#c8922a\" stroke-width=\"1.5\" stroke-dasharray=\"4,4\"/><text x=\"160\" y=\"185\" text-anchor=\"middle\" font-size=\"10\" fill=\"#a87418\">x̄</text><text x=\"16\" y=\"99\" text-anchor=\"middle\" font-size=\"10\" fill=\"#a87418\">ȳ</text><circle cx=\"55\" cy=\"150\" r=\"4\" fill=\"#b06000\"/><circle cx=\"75\" cy=\"130\" r=\"4\" fill=\"#b06000\"/><circle cx=\"100\" cy=\"140\" r=\"4\" fill=\"#b06000\"/><circle cx=\"120\" cy=\"110\" r=\"4\" fill=\"#b06000\"/><circle cx=\"145\" cy=\"100\" r=\"4\" fill=\"#b06000\"/><circle cx=\"175\" cy=\"80\" r=\"4\" fill=\"#b06000\"/><circle cx=\"200\" cy=\"70\" r=\"4\" fill=\"#b06000\"/><circle cx=\"225\" cy=\"55\" r=\"4\" fill=\"#b06000\"/><circle cx=\"250\" cy=\"45\" r=\"4\" fill=\"#b06000\"/><circle cx=\"270\" cy=\"35\" r=\"4\" fill=\"#b06000\"/><text x=\"235\" y=\"150\" text-anchor=\"middle\" font-size=\"11\" fill=\"#555\" font-style=\"italic\">Cov&gt;0: cresc împreună</text></svg>",intuitiv_text:"Cu cât ești mai mare, cu atât ești, de obicei, mai înalt - vârsta și înălțimea cresc împreună. <span class=\"hl\">Covarianța arată dacă două lucruri cresc împreună (covarianță pozitivă) sau dacă, atunci când unul crește, celălalt scade (covarianță negativă).</span> Corelația face același lucru, dar pusă pe o scală de la −1 la 1, ca să poți compara ușor cât de strânsă este legătura, indiferent de unitățile de măsură folosite.",intuitiv_nota:"Francis Galton a introdus ideea de corelație în studiul eredității (anii 1880), iar Karl Pearson a formalizat coeficientul de corelație liniară care îi poartă numele. Corelație zero nu implică independență, decât în cazuri speciale (ex. variabile normale).",exercitii:[{"q":"X ia valorile 1,2,3 cu probabilitate egală. Y=2X. Calculează Cov(X,Y).","pasi":["Calculăm media lui X: E[X] = (1+2+3)/3 = 2.","Calculăm media pătratelor: E[X²] = (1+4+9)/3 = 14/3.","Cum Y=2X, covarianța devine Cov(X,Y) = 2×Var(X) = 2×(E[X²]−(E[X])²) = 2×(14/3−4) = 2×(2/3) = 4/3."],"r":"✓ Cov(X,Y) = <strong>4/3 ≈ 1.33</strong>"},{"q":"Se știe că ρ(X,Y)=0.8, σ_X=2 și σ_Y=5. Află Cov(X,Y).","pasi":["Pornim de la formula ρ(X,Y) = Cov(X,Y)/(σ_X·σ_Y) și o inversăm: Cov(X,Y) = ρ(X,Y)×σ_X×σ_Y.","Înlocuim valorile: Cov(X,Y) = 0.8 × 2 × 5.","Calculăm: 0.8×2=1.6, apoi 1.6×5=8."],"r":"✓ Cov(X,Y) = <strong>8</strong>"},{"q":"Y = −3X + 7 (relație liniară perfectă, dar descrescătoare). Ce valoare are ρ(X,Y)?","pasi":["Când Y este o funcție liniară de X cu pantă negativă, relația dintre X și Y este perfectă, dar inversă: când X crește, Y scade exact proporțional.","Cov(X,Y) = Cov(X,−3X+7) = −3×Var(X), iar σ_Y = 3×σ_X (constanta multiplicativă luată în valoare absolută).","Atunci ρ = Cov(X,Y)/(σ_X×σ_Y) = −3Var(X)/(σ_X×3σ_X) = −3Var(X)/(3Var(X)) = −1."],"r":"✓ ρ(X,Y) = <strong>−1</strong> (relație liniară perfectă, dar descrescătoare)"},{"q":"Adevărat sau fals: dacă ρ(X,Y)=0, atunci X și Y sunt neapărat independente.","pasi":["Fals. Corelația zero arată doar absența unei legături liniare între X și Y.","X și Y pot avea o legătură puternică, dar neliniară (de exemplu, Y=X² cu X simetric în jurul lui 0), și totuși să aibă ρ=0.","Independența este o condiție mai tare decât corelația zero: ea implică ρ=0, dar reciproca nu este, în general, adevărată."],"r":"✓ <strong>Fals</strong> - corelație zero nu înseamnă independență"},{"q":"La o gelaterie se observă că, pe măsură ce crește temperatura zilnică X (°C), cresc și vânzările de înghețată Y (lei). Se știe că Cov(X,Y)=45, σ_X=3 și σ_Y=20. Calculează ρ(X,Y) și interpretează rezultatul.","pasi":["Aplicăm formula ρ(X,Y) = Cov(X,Y)/(σ_X×σ_Y).","Înlocuim valorile: ρ = 45/(3×20) = 45/60.","Simplificăm fracția: 45/60 = 0.75."],"r":"✓ ρ(X,Y) = <strong>0.75</strong> - o legătură liniară pozitivă puternică între temperatură și vânzări"}]};
